@testable import Dogear
import Foundation
@preconcurrency import ReadiumNavigator
@preconcurrency import ReadiumShared
import Testing
import UIKit
import WebKit

/// Seam 2: the CFI bridge on a real Readium navigator, with a fixture EPUB whose spine has a
/// `linear="no"` item before the target chapter.
@MainActor
struct CFIBridgeTests {
    /// Generated by foliate's epubcfi.js on the fixture: the start of "The keeper wrote down 40 gulls"
    /// in Chapter Two's paragraph 40, many pages into the chapter.
    static let webReaderCFI = "epubcfi(/6/8[itemref-ch2]!/4[chapter-two]/82/1:24)"

    @Test(.timeLimit(.minutes(3)))
    func webReaderCFILandsOnItsTextAndRoundTrips() async throws {
        let reader = try await OpenReader()

        let resolved = await reader.bridge.go(to: Self.webReaderCFI)

        #expect(resolved)
        #expect(reader.navigator.currentLocation?.href.string == "OEBPS/text/chapter-2.xhtml")
        let visible = try #require(await reader.bridge.visibleRange())
        #expect(await reader.text(of: visible).contains("Chapter 2 paragraph 40. The keeper wrote down 40 gulls"))
        #expect(await reader.contains(visible, Self.webReaderCFI))

        let generated = try #require(await reader.bridge.currentPosition())
        #expect(generated.hasPrefix("epubcfi(/6/8[itemref-ch2]!/4[chapter-two]/"))
        #expect(!generated.contains(","), "a point CFI, not a range")
        #expect(await reader.bridge.isSameStart(generated, visible))

        // Reopening at the written CFI, as the web reader or another device would, shows the same page.
        #expect(await reader.bridge.go(to: generated))
        let regenerated = try #require(await reader.bridge.currentPosition())
        #expect(await reader.bridge.isSameStart(regenerated, generated))
    }

    @Test(.timeLimit(.minutes(3)))
    func cfiOutsideTheReadingOrderDoesNotResolve() async throws {
        let reader = try await OpenReader()

        // The non-linear notes, which Readium's navigator can't show.
        #expect(await !reader.bridge.go(to: "epubcfi(/6/4!/4[notes]/2/1:0)"))
        #expect(await !reader.bridge.go(to: "epubcfi(/6/40!/4/2/1:0)"))
    }
}

/// The fixture EPUB open in a navigator on screen, with the bridge's scripts installed.
@MainActor
private final class OpenReader: EPUBNavigatorDelegate {
    let navigator: EPUBNavigatorViewController
    private(set) var bridge: CFIBridge!
    private let window: UIWindow
    private var locations = 0

    init() async throws {
        let folder = try #require(Bundle(for: OpenReader.self).url(forResource: "LighthouseLedger", withExtension: nil))
        let container = try await DirectoryContainer(directory: try #require(FileURL(url: folder)))
        let publication = try await openEPUB(in: container, httpClient: DefaultHTTPClient())
        // Readium leaves the linear="no" notes out, so reading order and spine indices differ.
        try #require(publication.readingOrder.map(\.href) == [
            "OEBPS/text/cover.xhtml", "OEBPS/text/chapter-1.xhtml", "OEBPS/text/chapter-2.xhtml", "OEBPS/text/chapter-3.xhtml",
        ])
        let spine = try #require(await CFIBridge.spine(of: publication))
        navigator = try EPUBNavigatorViewController(publication: publication, initialLocation: nil)
        // Pages are only laid out in a window that belongs to the host app's scene.
        let scene = try #require(UIApplication.shared.connectedScenes.compactMap { $0 as? UIWindowScene }.first)
        window = UIWindow(windowScene: scene)
        bridge = CFIBridge(navigator: navigator, publication: publication, spine: spine)
        navigator.delegate = self
        window.rootViewController = navigator
        window.makeKeyAndVisible()
        // A fresh simulator's WebKit can take a while to show the first page.
        for _ in 0 ..< 1200 where locations == 0 {
            try await Task.sleep(for: .milliseconds(50))
        }
        try #require(locations > 0, "the navigator never showed a page")
    }

    /// Text of `cfi`'s range in the current page.
    func text(of cfi: String) async -> String {
        await bridge.evaluate("""
        (() => { const p = CFI.parse(\(CFIBridge.literal(cfi))); (p.parent ?? p).shift(); return CFI.toRange(document, p).toString().replace(/\\s+/g, ' ') })()
        """) as? String ?? ""
    }

    /// Whether `point` lies within `range`.
    func contains(_ range: String, _ point: String) async -> Bool {
        await bridge.evaluate("""
        CFI.compare(CFI.collapse(\(CFIBridge.literal(range))), \(CFIBridge.literal(point))) <= 0
            && CFI.compare(\(CFIBridge.literal(point)), CFI.collapse(\(CFIBridge.literal(range)), true)) <= 0
        """) as? Bool == true
    }

    func navigator(_ navigator: EPUBNavigatorViewController, setupUserScripts userContentController: WKUserContentController) {
        for script in CFIBridge.userScripts { userContentController.addUserScript(script) }
    }

    func navigator(_ navigator: Navigator, locationDidChange locator: Locator) {
        locations += 1
        bridge?.locationDidChange()
    }

    func navigator(_ navigator: Navigator, presentError error: NavigatorError) {}
}
